 "content": "from collections import Counter, deque

def transform(grid):
    """Stamp the largest connected non-background object at every isolated marker."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc, grid[rr][cc]))
                for nr, nc in ((rr-1,cc), (rr+1,cc), (rr,cc-1), (rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            components.append(comp)
    exemplar = max(components, key=len)
    exemplar_cells = {(r,c) for r,c,_ in exemplar}
    non_exemplar = [grid[r][c] for r in range(h) for c in range(w)
                    if grid[r][c] != bg and (r,c) not in exemplar_cells]
    marker = Counter(non_exemplar).most_common(1)[0][0]
    # Markers align to the bounding-box center of the exemplar.
    ar = (min(r for r,c,_ in exemplar) + max(r for r,c,_ in exemplar)) // 2
    ac = (min(c for r,c,_ in exemplar) + max(c for r,c,_ in exemplar)) // 2
    offsets = [(r-ar, c-ac, color) for r,c,color in exemplar]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and (r,c) not in exemplar_cells:
                for dr, dc, color in offsets:
                    rr, cc = r+dr, c+dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
